_s3_bagit() {
    local cur prev cmd="" opts="" valued="" i
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"
    for ((i = 1; i < COMP_CWORD; i++)); do
        if [[ "${COMP_WORDS[i]}" != -* ]]; then
            cmd="${COMP_WORDS[i]}"
            break
        fi
    done
    case "$cmd" in
        "") opts="-h --help --version -v --verbose" ;;
        extract) opts="-h --help --no-verify --strip-top-level --dry-run"; valued="" ;;
        verify) opts="-h --help"; valued="" ;;
        verify-against) opts="-h --help"; valued="" ;;
        create-bag) opts="-h --help --bag-name --algorithm --bag-info"; valued="--bag-name --algorithm --bag-info" ;;
        ls) opts="-h --help"; valued="" ;;
        config) opts="-h --help --profile"; valued="--profile" ;;
        issue) opts="-h --help"; valued="" ;;
        *) return 0 ;;
    esac
    if [[ -n "$valued" && " $valued " == *" $prev "* ]]; then
        return 0
    fi
    if [[ "$cur" == -* ]]; then
        mapfile -t COMPREPLY < <(compgen -W "$opts" -- "$cur")
    elif [[ -z "$cmd" ]]; then
        mapfile -t COMPREPLY < <(compgen -W "extract verify verify-against create-bag ls config issue" -- "$cur")
    fi
    return 0
}
complete -F _s3_bagit s3-bagit
